<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Smartwatch Secondary Market Analysis — Q1 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #242836;
    --border: #2e3347;
    --text: #e4e6ef;
    --text-dim: #8b8fa3;
    --accent: #6366f1;
    --accent2: #818cf8;
    --green: #34d399;
    --red: #f87171;
    --amber: #fbbf24;
