    -webkit-text-fill-color: transparent;
  }
  .report-header .subtitle {
    color: var(--text-dim);
    font-size: 1rem;
    max-width: 700px;
    margin: 0 auto;
  }
  .report-header .meta {
    margin-top: 16px;
    font-size: 0.8rem;
    color: var(--text-dim);
