  /* Footer */
  .report-footer {
    text-align: center;
    padding: 32px 24px;
    border-top: 1px solid var(--border);
    margin-top: 48px;
    color: var(--text-dim);
    font-size: 0.78rem;
  }
</style>
</head>
<body>

<div class="report-header">
  <h1>Global Smartwatch Secondary Market Analysis</h1>
  <p class="subtitle">Q1 2026 — Analysis of 3,607 resale listings across Apple, Garmin, and Samsung to uncover pricing dynamics, geographic arbitrage, and seller behavior patterns.</p>
  <p class="meta">Dataset: 3,607 listings &bull; 1,754 sellers &bull; 27 countries &bull; $70 price floor applied</p>
</div>

<div class="container">

<!-- KPI Cards -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Apple Median Price</div>
    <div class="kpi-value apple">$550</div>
    <div class="kpi-detail">2,370 listings (65.7%)</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Garmin Median Price</div>
