      </tr>
      <tr>
        <td><span class="brand-tag garmin">Garmin</span></td>
        <td class="num">746</td>
        <td class="num">$566.98</td>
        <td class="num">$628.05</td>
        <td class="num">$467.52</td>
        <td class="num">$749.99</td>
        <td class="num">$282.47</td>
        <td class="num">$215.10</td>
        <td class="num">$1,319</td>
      </tr>
      <tr>
        <td><span class="brand-tag samsung">Samsung</span></td>
        <td class="num">470</td>
        <td class="num">$530.00</td>
        <td class="num">$725.49</td>
        <td class="num">$449.96</td>
